  private readonly inFlightGetRequests = new Map<string, Promise<any>>();

  public constructor() {
    super({});
  }

  private dedupeGetRequest<T>(
    key: string,
    requestFactory: () => Promise<T>,
  ): Promise<T> {
    const inFlightRequest = this.inFlightGetRequests.get(key);
    if (inFlightRequest) {
      logger.debug(`[API] Joining in-flight GET request: ${key}`);
      return inFlightRequest as Promise<T>;
    }

    const request = requestFactory().finally(() => {
      if (this.inFlightGetRequests.get(key) === request) {
        this.inFlightGetRequests.delete(key);
      }
    });

    this.inFlightGetRequests.set(key, request);
    return request;
  }

