  protected async handleSubscriptionError(error: unknown): Promise<any> {
    if (error instanceof Error && error.message.includes('401')) {
      const auth_token_store = await this.getAuthTokenStore();
      auth_token_store.tryToRefreshToken(true);
      throw { message: 'Unauthorized' };
    }

    if (error instanceof Error && error.message.includes('400')) {
      throw { message: 'Unauthorized' };
    }

    if (error instanceof Error && error.message.includes('timeout')) {
      throw { message: 'timeout' };
    }

    if (error instanceof Error && error.message == 'Network Error') {
      throw { message: 'network_error' };
    }

    if (
      this.isAxiosError(error) &&
      error.response &&
      error.response.status &&
      error.response.status === 500
    ) {
      throw { message: 'network_error' };
    }

    throw error;
  }

