  public async checkIfSystemAdminExists(): Promise<boolean> {
    try {
      const res = await this.getUsers();
      if (Array.isArray(res) && res.length > 0) {
        // Check if any user has is_system_user === true
        return res.some((user: any) => user.is_system_user === true);
      }
      return false;
    } catch (error) {
      // logError('Failed to check system admin:', error);
      console.error('Failed to check system admin:', error);
      return false;
    }
  }

