// ============================================================
// API Key TypeScript Interfaces
// ============================================================

/**
 * API Key object returned from the backend
 */
export interface ApiKey {
  id: string;
  key_prefix: string;
  name: string | null;
  description: string | null;
  expires_at: string | null;
  last_used_at: string | null;
  is_active: boolean;
  created_at: string;
  revoked_at: string | null;
}

/**
 * Response from GET /api/api-keys (list)
 */
export interface ApiKeysListResponse {
  keys: ApiKey[];
}

/**
 * Request body for POST /api/api-keys (create)
 */
export interface CreateApiKeyRequest {
  name: string;
  description?: string;
  expires_at?: string | null;
}

/**
 * Response from POST /api/api-keys (create)
 * Note: 'key' field contains the full API key and is only shown once!
 */
export interface CreateApiKeyResponse {
  id: string;
  key: string; // Full API key - shown only once!
  key_prefix: string;
  name: string;
  description: string | null;
  expires_at: string | null;
  created_at: string;
}

/**
 * Response from GET /api/api-keys/{id} (single key details)
 */
export interface ApiKeyResponse extends ApiKey {}

/**
 * Request body for PATCH /api/api-keys/{id} (update)
 */
export interface UpdateApiKeyRequest {
  name?: string;
  description?: string;
}

/**
 * Response from DELETE /api/api-keys/{id} (revoke)
 */
export interface RevokeApiKeyResponse {
  success: boolean;
  message?: string;
}
