import type { dynamicObj } from 'src/pages/assets';
import { objLen } from 'src/utils/general';

/**
 * New API response format:
 * {
 *   "success": true,
 *   "is_admin": false,
 *   "permissions": {
 *     "INVOICE": { "edit": 0, "delete": 1, "view": 0, ... },
 *     "CREDIT_NOTE": { ... }
 *   }
 * }
 */
export const Formatter = {
  formatServerAClsResponse: function (acls_data: dynamicObj) {
    if (!acls_data || objLen(acls_data) < 1) {
      return {};
    }

    const user_acls = {} as dynamicObj;

    // Set is_admin flag from API response
    user_acls.is_admin = acls_data.is_admin ?? false;

    // Copy permissions directly from new API format
    if (acls_data.permissions && typeof acls_data.permissions === 'object') {
      for (const [docKey, permissions] of Object.entries(acls_data.permissions)) {
        user_acls[docKey] = permissions;
      }
    }

    return user_acls;
  },
};
