import { api } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';
import type { dynamicObj } from 'src/pages/assets';

export default class NotificationsApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  public async markNotificationAsRead(id: string): Promise<any> {
    const api_data: any = {};
    api_data['seen'] = String(true);
    return super.patch(api.notifications + id, api_data);
  }
  public async getNotifications(params: dynamicObj): Promise<any> {
    const querystring = this.encodeQueryData(params);
    return super.get(api.notifications + '?' + querystring, {});
  }
}
