import { REGION_STORAGE_KEY } from 'src/constants';

export type ApiRegion = 'eu' | 'us';

const branch = process.env.APP_VUE_BRANCH ? process.env.APP_VUE_BRANCH + '.' : '';
const wsBranch = branch || 'dev.';

const REGIONAL_STAGES = new Set(['prod', 'sandbox']);

export function isRegionalStage(): boolean {
  return REGIONAL_STAGES.has(process.env.APP_VUE_STAGE || '');
}

function buildApiUrl(region: ApiRegion): string {
  if (!isRegionalStage()) {
    return 'https://' + branch + 'api.docbits.com';
  }
  const prefix = region === 'us' ? 'us.' : 'eu.';
  return 'https://' + prefix + branch + 'api.docbits.com';
}

function buildWebSocketUrl(region: ApiRegion): string {
  if (!isRegionalStage()) {
    return 'https://' + wsBranch + 'api.docbits.com';
  }
  const prefix = region === 'us' ? 'us.' : 'eu.';
  return 'https://' + prefix + wsBranch + 'api.docbits.com';
}

export function getCurrentApiRegion(): ApiRegion | null {
  if (typeof window === 'undefined') return null;
  try {
    const direct = window.localStorage.getItem(REGION_STORAGE_KEY);
    if (direct === '"us"' || direct === 'us') return 'us';
    if (direct === '"eu"' || direct === 'eu') return 'eu';
    const userRaw = window.localStorage.getItem('user_details');
    if (userRaw) {
      const parsed = JSON.parse(userRaw);
      const orgs: Array<{ is_default?: boolean; region?: string }> = Array.isArray(
        parsed?.organisations,
      )
        ? parsed.organisations
        : [];
      const defaultOrg = orgs.find((o) => o?.is_default) ?? orgs[0];
      if (defaultOrg?.region === 'us') return 'us';
      if (defaultOrg?.region === 'eu') return 'eu';
    }
  } catch {
    // fall through
  }
  return 'eu';
}

export function persistApiRegion(region: ApiRegion | undefined | null): void {
  if (typeof window === 'undefined') return;
  const resolved: ApiRegion = region === 'us' ? 'us' : 'eu';
  try {
    window.localStorage.setItem(REGION_STORAGE_KEY, JSON.stringify(resolved));
  } catch {
    // ignore quota / disabled storage
  }
}

export function clearPersistedApiRegion(): void {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.removeItem(REGION_STORAGE_KEY);
  } catch {
    // ignore
  }
}

export function enforceRegionOnUrl(url: string): string {
  if (!url || !isRegionalStage()) return url;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }
  const host = parsed.hostname;
  if (!host.endsWith('.docbits.com')) return url;
  const stripped = host.replace(/^(us|eu)\./, '');
  if (stripped === 'auth.docbits.com' || stripped.endsWith('.auth.docbits.com')) {
    return url;
  }
  const region = getCurrentApiRegion();
  const expectedHost = (region === 'us' ? 'us.' : 'eu.') + stripped;
  if (host === expectedHost) return url;
  parsed.hostname = expectedHost;
  return parsed.toString();
}

export let DOC2API_URL = buildApiUrl(getCurrentApiRegion());
export let WEB_SOCKET_URL = buildWebSocketUrl(getCurrentApiRegion());

type ApiBaseUrlListener = (url: string) => void;
const apiBaseUrlListeners: ApiBaseUrlListener[] = [];

export function onApiBaseUrlChange(cb: ApiBaseUrlListener): void {
  apiBaseUrlListeners.push(cb);
  cb(DOC2API_URL);
}

type ApiRegionListener = (region: ApiRegion) => void;
const apiRegionListeners: ApiRegionListener[] = [];

export function onApiRegionChange(cb: ApiRegionListener): void {
  apiRegionListeners.push(cb);
  cb(getCurrentApiRegion());
}

export function setApiRegion(region: ApiRegion | undefined | null): void {
  const resolved: ApiRegion = region === 'us' ? 'us' : 'eu';
  persistApiRegion(resolved);
  const nextApi = buildApiUrl(resolved);
  const nextWs = buildWebSocketUrl(resolved);
  const urlChanged = nextApi !== DOC2API_URL || nextWs !== WEB_SOCKET_URL;
  if (urlChanged) {
    DOC2API_URL = nextApi;
    WEB_SOCKET_URL = nextWs;
    for (const cb of apiBaseUrlListeners) cb(DOC2API_URL);
  }
  for (const cb of apiRegionListeners) cb(resolved);
}
