import { defineStore } from 'pinia';
import IdeasApiService from 'src/services/ideas/IdeasApiService';
import type {
  Idea,
  IdeaCategory,
  IdeaComment,
  IdeaStatus,
  PaginationInfo,
  CreateIdeaPayload,
  UpdateIdeaPayload,
} from 'src/types/api/ideas';

const ideasApiService = new IdeasApiService();

export const useIdeasStore = defineStore('ideas', {
  state: () => ({
    ideas: [] as Idea[],
    loading: false,
    myVotes: new Set<string>(),
    pagination: {
      current_page: 1,
      page_size: 20,
      total_entries: 0,
      total_pages: 0,
      has_next_page: false,
    } as PaginationInfo,
    comments: {} as Record<string, IdeaComment[]>,
    filters: {
      category: null as IdeaCategory | null,
      status: null as IdeaStatus | null,
      search: '',
      sort: 'newest' as string,
    },
  }),

  getters: {
    hasVoted: (state) => (ideaId: string) => state.myVotes.has(ideaId),
  },

  actions: {
    async loadIdeas(page?: number) {
      this.loading = true;
      try {
        const currentPage = page || this.pagination.current_page;
        const [listResult, votesResult] = await Promise.all([
          ideasApiService.getIdeas({
            page: currentPage,
            page_size: this.pagination.page_size,
            category: this.filters.category || undefined,
            status: this.filters.status || undefined,
            search: this.filters.search || undefined,
            sort: this.filters.sort,
          }),
          ideasApiService.getMyVotes(),
        ]);

        if (listResult.success) {
          this.ideas = listResult.ideas;
          this.pagination = listResult.pagination;
        }

        if (votesResult.success) {
          this.myVotes = new Set(votesResult.idea_ids);
        }
      } catch (error) {
        console.error('Failed to load ideas:', error);
      } finally {
        this.loading = false;
      }
    },

    async createIdea(payload: CreateIdeaPayload) {
      try {
        const result = await ideasApiService.createIdea(payload);
        if (result.success) {
          this.ideas.unshift(result.idea);
          this.pagination.total_entries += 1;
          return result.idea;
        }
      } catch (error) {
        console.error('Failed to create idea:', error);
        throw error;
      }
    },

    async toggleVote(ideaId: string) {
      const previouslyVoted = this.myVotes.has(ideaId);
      const idea = this.ideas.find((i) => i.id === ideaId);

      // Optimistic update
      if (idea) {
        if (previouslyVoted) {
          this.myVotes.delete(ideaId);
          idea.vote_count = Math.max(0, idea.vote_count - 1);
        } else {
          this.myVotes.add(ideaId);
          idea.vote_count += 1;
        }
      }

      try {
        const result = await ideasApiService.toggleVote(ideaId);
        if (result.success && idea) {
          idea.vote_count = result.vote_count;
          if (result.voted) {
            this.myVotes.add(ideaId);
          } else {
            this.myVotes.delete(ideaId);
          }
        }
      } catch (error) {
        // Revert optimistic update
        if (idea) {
          if (previouslyVoted) {
            this.myVotes.add(ideaId);
            idea.vote_count += 1;
          } else {
            this.myVotes.delete(ideaId);
            idea.vote_count = Math.max(0, idea.vote_count - 1);
          }
        }
        console.error('Failed to toggle vote:', error);
      }
    },

    async updateStatus(ideaId: string, status: IdeaStatus) {
      try {
        const result = await ideasApiService.updateStatus(ideaId, status);
        if (result.success) {
          const idea = this.ideas.find((i) => i.id === ideaId);
          if (idea) {
            idea.status = status;
          }
        }
      } catch (error) {
        console.error('Failed to update status:', error);
        throw error;
      }
    },

    async updateIdea(ideaId: string, payload: UpdateIdeaPayload) {
      try {
        const result = await ideasApiService.updateIdea(ideaId, payload);
        if (result.success) {
          const idea = this.ideas.find((i) => i.id === ideaId);
          if (idea) {
            if (payload.title !== undefined) idea.title = payload.title;
            if (payload.description !== undefined) idea.description = payload.description;
            if (payload.category !== undefined) idea.category = payload.category;
          }
          return result.idea;
        }
      } catch (error) {
        console.error('Failed to update idea:', error);
        throw error;
      }
    },

    async loadComments(ideaId: string) {
      try {
        const result = await ideasApiService.getComments(ideaId);
        if (result.success) {
          this.comments[ideaId] = result.comments;
        }
        return result.comments;
      } catch (error) {
        console.error('Failed to load comments:', error);
        throw error;
      }
    },

    async addComment(ideaId: string, content: string) {
      try {
        const result = await ideasApiService.createComment(ideaId, { content });
        if (result.success) {
          this.comments[ideaId] = result.comments;
        }
        return result.comments;
      } catch (error) {
        console.error('Failed to add comment:', error);
        throw error;
      }
    },

    async removeComment(ideaId: string, commentId: string) {
      try {
        const result = await ideasApiService.deleteComment(ideaId, commentId);
        if (result.success) {
          this.comments[ideaId] = (this.comments[ideaId] || []).filter(
            (c) => c.id !== commentId,
          );
        }
      } catch (error) {
        console.error('Failed to remove comment:', error);
        throw error;
      }
    },

    async deleteIdea(ideaId: string) {
      try {
        const result = await ideasApiService.deleteIdea(ideaId);
        if (result.success) {
          this.ideas = this.ideas.filter((i) => i.id !== ideaId);
          this.pagination.total_entries = Math.max(
            0,
            this.pagination.total_entries - 1,
          );
        }
      } catch (error) {
        console.error('Failed to delete idea:', error);
        throw error;
      }
    },

    setFilter(key: 'category' | 'status' | 'search' | 'sort', value: string | null) {
      if (key === 'search') {
        this.filters.search = value || '';
      } else if (key === 'sort') {
        this.filters.sort = value || 'newest';
      } else {
        (this.filters as Record<string, unknown>)[key] = value;
      }
    },

    resetFilters() {
      this.filters.category = null;
      this.filters.status = null;
      this.filters.search = '';
      this.filters.sort = 'newest';
    },
  },
});
