import { i18n } from 'src/boot/i18n';
export default {
  methods: {
    getDocTypeLabel(row) {
      let label = '';
      try {
        const translation_key = row.translation_key
          ? row.translation_key
          : row.type;
        const translation = this.translateDocType(translation_key);

        label = '-';
        if (row.hasOwnProperty('title') && row.title !== '') {
          label = row.title;
        } else {
          label = translation;
        }

        if (translation !== translation_key) {
          label = translation;
        }
      } catch (err) {
        logError(err);
      }
      return label;
    },

    displayDocType(type, prefix = 'pages.settings.') {
      let label = '';
      try {
        const translation_key = prefix + type;
        const title = type;
        const translation = this.translateDocType(translation_key);
        label = type
          ? translation === translation_key
            ? title
                .toLowerCase()
                .replace(/_/g, ' ')
                .replace(/\b[a-z]/g, function (match) {
                  return String(match).toUpperCase();
                })
            : translation
          : '-';
      } catch (err) {
        logError(err);
      }
      return label;
    },

    translateDocType(translation_key) {
      let translation = '';
      try {
        translation = !translation_key ? '' : i18n.t(translation_key);
      } catch (err) {
        logError(err);
      }
      return translation;
    },

    getDocTypeForDisplay(row) {
      if (!row.doc_type) {
        return '';
      }
      let type = row.sub_doc_type ? row.sub_doc_type : row.doc_type;
      return String(type);
    },
  },
};
