import { uid } from 'quasar';
import { defineStore } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { masterDataApiService } from 'src/services';
import { usePoMatchStore, useSettingStore } from 'src/store/main';
import {
  auto_accounting_setting,
  auto_accounting_types_setting,
  auto_accounting_acc_list_name_setting,
  auto_accounting_po_acc_list_name_setting,
  auto_accounting_dimensions_list_setting,
  auto_accounting_dimensions_options_setting,
  auto_accounting_fields_setting,
} from 'src/constants';
import { hasValue, isUndefinedOrNull, objLen } from 'src/utils/general';

export interface AdditionalField {
  field_name: string;
  [key: string]: unknown;
}

export const useAccountingTypeStore = defineStore('accounting_type_store', {
  state: () => ({
    view_template: '' as string,
    view_types: {
      ln: 'LN_VIEW',
      m3: 'M3_VIEW',
    } as const,
    line_item_loaded: false,
    accounts_promise_resolve: null as ((value: unknown) => void) | null,
    accounting_additional_fields: {} as Record<string, AdditionalField>,
    settings_store: useSettingStore(),
    masterDataLimit: 99999,
  }),
  getters: {},
  actions: {
    resetAccountingTypeStore() {
      this.line_item_loaded = false;
      this.view_template = '';
      this.accounts_promise_resolve = null;
    },

    getbaseTotalLineItem() {
      const line = this.baseLineItem();
      line.type = 'total_line_item';
      line.amount_readonly = true;

      delete line.checked;
      return line;
    },

    baseLineItem() {
      if (this.view_template === 'LN_VIEW') {
        return this.getLNLineItem();
      }
      return this.getM3LineItem();
    },

    baseSplitLineItem() {
      if (this.view_template === 'LN_VIEW') {
        return this.getLNSplitLineItem();
      }
      return this.getM3SplitLineItem();
    },

    getM3LineItem() {
      return {
        id: '',
        type: 'line_item',
        account: '',
        voucher_text: '',
        account_error: '',
        amount: '',
        amount_standard: 0,
        amount_readonly: false,
        checked: '',
        split_items: [],
        amount_error: '',
        position: '',
        dimensions: [],
        readonly: false,
        error: '',
        pending_amount: '0',
        lines_total_amount: '0',
        description: '',
        item_number: '',
      } as dynamicObj;
    },

    getLNLineItem() {
      const line = {
        id: '',
        type: 'line_item',
        account: '',
        account_error: '',
        amount: '',
        amount_standard: 0,
        amount_readonly: false,
        checked: '',
        split_items: [],
        amount_error: '',
        position: '',
        dimensions: [],
        readonly: false,
        error: '',
        pending_amount: '0',
        lines_total_amount: '0',
        description: '',
        item_number: '',
        booking_reference: '',
      } as dynamicObj;

      if (this.hasAdditionalFields()) {
        for (const field of Object.values(
          this.accounting_additional_fields as Record<string, AdditionalField>,
        )) {
          line[field.field_name] = '';
        }
      }
      return line;
    },

    getLNSplitLineItem() {
      const split_line = {
        id: uid(),
        account: '' as string | dynamicObj,
        percentage: '',
        amount: '',
        amount_standard: 0,
        amount_error: '',
        percentage_error: '',
        account_error: '',
        is_validated: true,
        booking_reference: '',
      } as dynamicObj;

      if (this.hasAdditionalFields()) {
        for (const field of Object.values(
          this.accounting_additional_fields as Record<string, AdditionalField>,
        )) {
          split_line[field.field_name] = '';
        }
      }
      return split_line;
    },

    getM3SplitLineItem() {
      return {
        id: uid(),
        account: '' as string | dynamicObj,
        percentage: '',
        amount: '',
        amount_standard: 0,
        amount_error: '',
        percentage_error: '',
        account_error: '',
        is_validated: true,
        voucher_text: '',
      };
    },

    verifyModuleSettings() {
      const errors_list = [] as string[];
      const settings_store = useSettingStore();
      const { user_settings } = settings_store;

      if (!user_settings[auto_accounting_setting]) {
        errors_list.push('auto accounting settings not enabled');
        return errors_list;
      }

      if (user_settings[auto_accounting_types_setting] === 'm3') {
        const po_match_store = usePoMatchStore();
        const { hasPoMatchData } = po_match_store;
        if (
          hasPoMatchData() &&
          !hasValue(user_settings[auto_accounting_po_acc_list_name_setting])
        ) {
          errors_list.push(auto_accounting_po_acc_list_name_setting);
          return errors_list;
        }
      }

      let settings = [auto_accounting_acc_list_name_setting];

      const ln_settings = [
        auto_accounting_dimensions_list_setting,
        auto_accounting_dimensions_options_setting,
      ];
      if (user_settings[auto_accounting_types_setting] === 'ln') {
        settings = settings.concat(ln_settings);
      }

      for (const setting of settings) {
        if (!hasValue(user_settings[setting])) {
          errors_list.push(setting);
        }
      }

      return errors_list;
    },

    // Additional fileds
    getAdditionalFields() {
      const settings_store = useSettingStore();
      const additional_fields =
        settings_store.user_settings[auto_accounting_fields_setting];
      let additional_fields_obj = {} as dynamicObj;
      try {
        if (additional_fields) {
          additional_fields_obj = JSON.parse(additional_fields);
        }
      } catch (error) {}

      return additional_fields_obj;
    },

    hasAdditionalFields() {
      return (
        !isUndefinedOrNull(this.accounting_additional_fields) &&
        objLen(this.accounting_additional_fields) > 0
      );
    },

    resetlineAdditionalFields(item: dynamicObj): dynamicObj {
      if (this.hasAdditionalFields()) {
        for (const field of Object.values(
          this.accounting_additional_fields as Record<string, AdditionalField>,
        )) {
          item[field.field_name] = '';
        }
      }
      return item;
    },

    dynamicAdditionalFieldStyle(): string {
      const fieldCount = objLen(this.accounting_additional_fields);

      // If there are no fields, don't apply any width (or you can hide it)
      if (fieldCount === 0) {
        return 'display: none';
      }

      // If more than 2 fields, divide the inner width equally
      if (fieldCount > 2) {
        return `width: ${100 / fieldCount}%`;
      }

      // If exactly 2 fields, divide the inner width by 50%
      if (fieldCount === 2) {
        return 'width: 50%';
      }

      // If 1 field, use full width
      return 'width: 100%';
    },

    async getMasterData(listName: string) {
      try {
        const request_params = this.prepareRequestData(listName);

        if (!request_params) {
          return [] as dynamicObj[];
        }

        const response = await masterDataApiService.getData_V2(
          request_params,
          '',
        );
        if (!response) {
          throw response;
        }
        return response.data as dynamicObj[];
      } catch (error) {
        throw error;
      }
    },

    prepareRequestData(settingName: string, includeSortOrder = false) {
      const dataType = this.getSettingsName(settingName);

      if (!dataType) {
        return null;
      }

      const request_params = {} as dynamicObj;
      request_params['skip'] = 0;
      request_params['limit'] = this.masterDataLimit;
      request_params['data_type'] = dataType;

      if (includeSortOrder) {
        request_params['sort_order_json'] = JSON.stringify([
          { field: 'nominalaccount', direction: 'asc' },
        ]);
      }

      return request_params;
    },

    getSettingsName(settingName: string): string | undefined {
      return this.settings_store.user_settings[settingName];
    },
  },
});
