import type { AxiosInstance, InternalAxiosRequestConfig } from 'axios';
import { enforceRegionOnUrl } from 'src/pages/api-base-url';

function fixRequestUrl(config: InternalAxiosRequestConfig): InternalAxiosRequestConfig {
  const url = config.url ?? '';
  const baseURL = config.baseURL ?? '';
  if (/^https?:\/\//i.test(url)) {
    const fixed = enforceRegionOnUrl(url);
    if (fixed !== url) config.url = fixed;
    return config;
  }
  if (baseURL && /^https?:\/\//i.test(baseURL)) {
    const joined =
      baseURL.replace(/\/$/, '') +
      (url ? (url.startsWith('/') ? url : '/' + url) : '');
    const fixed = enforceRegionOnUrl(joined);
    if (fixed !== joined) {
      config.baseURL = '';
      config.url = fixed;
    }
  }
  return config;
}

const installed = new WeakSet<AxiosInstance>();

export function installRegionInterceptor(instance: AxiosInstance): void {
  if (installed.has(instance)) return;
  installed.add(instance);
  instance.interceptors.request.use(fixRequestUrl);
}
