// JQL-style search parser for the dashboard quick-search input.
//
// Recognised syntax (inspired by Jira JQL, deliberately small so the
// free-text path stays the default for non-power users):
//
//   id=069e22da-...                  -- exact UUID lookup on document id
//   invoice_id=INV-2026-03-00284     -- exact match on a known field
//   purchase_order:"PO 42"           -- phrase match (quoted)
//   total_amount > 5000              -- numeric range (requires Fulltext)
//   invoice_due_date >= 2026-04-21   -- date range (requires Fulltext)
//
// Anything that doesn't parse as a predicate stays in the `keyword`
// string, which still works as the existing substring search. That
// keeps the UI forgiving: a user typing "invoice_id INV-42" without
// the equals sign still gets results.

export type SearchOperator =
  | '='
  | '!='
  | '>'
  | '<'
  | '>='
  | '<='
  | ':'
  | 'between';
export type LogicalConnector = 'AND' | 'OR';

export interface ParsedPredicate {
  field: string;
  operator: SearchOperator;
  value: string;
  // Logical connector to the PREVIOUS predicate (undefined for the first).
  // Defaults to AND when two predicates appear without an explicit keyword.
  connector?: LogicalConnector;
}

export interface ParsedSearch {
  // Structured field=value predicates extracted from the input.
  predicates: ParsedPredicate[];
  // Residual keyword (tokens that didn't match a predicate).
  keyword: string;
  // True when at least one predicate requires the Fulltext module
  // (range operators or an extracted-only field).
  requiresFulltext: boolean;
  // True when the user prefixed the query with "vector:" (opt-in
  // kNN semantic search). Requires the Vector module. Mutually
  // exclusive with `isAiMode` — a query has at most one prefix.
  isVectorMode: boolean;
  // True when the user prefixed the query with "ai:" (opt-in natural
  // language → structured query via the Ollama LLM in fulltextsearch).
  // Routes through fulltextsearch's ai_query_parser, NOT through kNN.
  // Requires fulltext to be enabled on the org.
  isAiMode: boolean;
  // True when the user prefixed the query with "ocr:" (explicit fulltext
  // search over OCR/table/text-companion content). Requires fulltext and must
  // not be routed through vector or AI.
  isOcrMode: boolean;
  // Optional inline sort directive — produced by the `... sort <field>
  // asc|desc` suffix. quick-search.vue applies these to the
  // dashboard's order_by_field/order_by_direction when present.
  sortOverride?: {
    field: string;
    direction: 'asc' | 'desc';
  };
  // Optional inline group-by directive — produced by the
  // `group by <field> [day|week|month]` suffix. quick-search.vue
  // forwards this to dashboard.vue's `selectedGroupBy` state so the
  // table renders backend-aggregated bucket rows. Mirrors the
  // sortOverride routing — directive lives outside the predicate stream.
  groupByOverride?: {
    field: string;
    bucket?: 'day' | 'week' | 'month';
  };
  // Per-chip category overrides keyed by field name. Populated only
  // by the chip-editor host (QuickSearchBox) — the raw-text parser
  // can't infer this because the section the user picked from is a
  // UI-only choice not visible in the serialised query string.
  //
  // Drives wire routing in `computeQuickSearchSlots`: a field like
  // `supplier_name` may appear in BOTH the EXTENDED and the FULLTEXT
  // dropdown sections. When the user picks from FULLTEXT, the chip
  // carries `category='fulltext'` — and the dashboard MUST send
  // `is_fulltext=true` so the request routes to OpenSearch instead
  // of the standard PG path (which would 422 because supplier_name
  // is not a column on `documents`).
  //
  // Lookup precedence: chip override > FIELD_CATALOG default > undefined.
  chipCategoryOverrides?: Map<
    string,
    'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr'
  >;
}

