// Aliases mapped to the canonical column name. Applied ONLY at the
// backend-serialisation edge (`canonicaliseForBackend`), never in the
// parsed predicate list or the chip editor. Keeps `imported_on=today()`
// visible exactly as the user typed it while the HTTP request still
// carries `created_on=2026-04-22`.
export const FIELD_ALIASES: Record<string, string> = {
  imported_on: 'created_on',
  updated: 'last_modified_on',
  updated_on: 'last_modified_on',
  // Procurement vocabulary — the underlying ClickHouse dashboard
  // column is `supplier_name` (constants/clickhouse.py). Frontend
  // accepts the procurement term `vendor_name` for both raw_query
  // predicates and group-by directives, and rewrites it to the
  // canonical column name BEFORE shipping to the backend so the
  // GROUP BY / WHERE clause references a real column.
  vendor_name: 'supplier_name',
};

// Field metadata used by the UI autocomplete. Three categories drive
// the colour in the search input:
//   - standard: blue  (fast Postgres path — always available)
//   - fulltext: orange (needs OpenSearch — range or extracted-only)
//   - vector:   purple (needs Vector module — semantic prefix)
//   - ocr:      green (needs Fulltext module — OCR/table content prefix)
// The `ops` list is only for the tooltip / hint — the parser accepts
// everything and the backend does the real validation.
export type ValueType = 'numeric' | 'date' | 'enum' | 'uuid' | 'string';

export interface FieldMeta {
  name: string;
  // 'standard' = direct documents-table column (fast PG path)
  // 'extended' = projected from document_extracted_data EAV onto a typed
  //              ClickHouse column via SYNC_COLUMNS — filterable as SQL
  //              column without OpenSearch round-trip.
  // 'fulltext' = needs OpenSearch (custom doc-type fields, range ops on
  //              non-projected fields).
  // 'vector'   = semantic-similarity prefix (vector:, ai:).
  // 'ocr'      = explicit OCR/table/text-companion prefix (ocr:).
  category: 'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr';
  ops: readonly string[]; // typical operators for this field
  // Drives smart-commit rules in QuickSearchBox — numeric/date/enum/uuid
  // values commit on space; string values wait for Enter/Tab so multi-
  // word strings aren't prematurely cut.
  valueType: ValueType;
  // Human-friendly label shown in the autocomplete dropdown. Overrides
  // the automatic Title-Case of `name`. Use this whenever the raw
  // identifier (invoice_id, ap_assignment_code) misleads the user
  // about what the field means (it's Invoice Number, not Invoice Id).
  // When omitted, FieldAutocomplete falls back to prettyFieldName(name).
  displayName?: string;
  // English description used as fallback / for parser tests / documentation.
  description: string;
  // i18n key resolved in the Vue layer via $t(). Keeping the English
  // fallback here lets non-Vue consumers (unit tests, tooling) read the
  // catalog without pulling in Tolgee.
  descriptionKey: string;
  // Short i18n key used as the chip label — one or two words, never a
  // sentence. The dropdown keeps descriptionKey (longer, descriptive);
  // chips use labelKey so rows stay compact. Falls back to descriptionKey
  // when omitted.
  labelKey?: string;
  example: string;
  // When true, the operator picker offers "is not empty" / "is empty"
  // presets that emit the complete `field!=""` / `field=""` predicate in
  // one click. Default false. Useful for fields that may be unset (most
  // extracted fulltext fields, plus a handful of standard columns).
  supportsPresence?: boolean;
  docTypes?: string[];
}

// MUTABLE on purpose: hydrated from the `extended_field_names` payload
// of `GET /document/search/fields` so custom doc-type fields tagged
// dynamically per org get the correct routing class. Empty fallback
// keeps the function pure during unit tests / pre-hydration boot —
// custom fields default to 'fulltext' until the catalog hydrator
// populates this set.
let _EXTENDED_FIELD_NAMES: ReadonlySet<string> = new Set();
let _CUSTOM_FIELD_NAMES: ReadonlySet<string> = new Set();

export function setExtendedFieldNames(
  names: ReadonlySet<string> | string[],
): void {
  _EXTENDED_FIELD_NAMES = names instanceof Set ? names : new Set(names);
}

export function getExtendedFieldNames(): ReadonlySet<string> {
  return _EXTENDED_FIELD_NAMES;
}

export function setCustomFieldNames(
  names: ReadonlySet<string> | string[],
): void {
  const values = Array.from(names);
  _CUSTOM_FIELD_NAMES = new Set(values.map((name) => name.toLowerCase()));
}

export function getCustomFieldNames(): ReadonlySet<string> {
  return _CUSTOM_FIELD_NAMES;
}

function isSupportedSearchField(fieldName: string): boolean {
  return (
    SUPPORTED_FIELDS.has(fieldName) ||
    _CUSTOM_FIELD_NAMES.has(fieldName) ||
    FIELD_CATALOG.some((field) => field.name === fieldName)
  );
}

export function customFieldsToFieldMetas(
  raw: {
    field_name: string;
    title: string;
    doc_types: string[];
    field_type?: string;
  }[],
): FieldMeta[] {
  const knownNames = new Set(FIELD_CATALOG.map((f) => f.name));
  setCustomFieldNames(raw.map((field) => field.field_name));
  return raw
    .filter((c) => !knownNames.has(c.field_name))
    .map((c) => {
      const fieldType = String(c.field_type ?? '').toUpperCase();
      const isNumeric = ['AMOUNT', 'NUMBER', 'CURRENCY', 'CHARGES'].includes(
        fieldType,
      );
      const isDate = fieldType === 'DATE';
      return {
        name: c.field_name,
        // Promote to 'extended' (teal) when the backend tells us this
        // field name is in SYNC_COLUMNS — it's then ClickHouse-projected
        // and SQL-filterable. Otherwise stays 'fulltext' (orange).
        category: (_EXTENDED_FIELD_NAMES.has(c.field_name)
          ? 'extended'
          : 'fulltext') as 'extended' | 'fulltext',
        ops: isNumeric
          ? ['=', '>', '<', '>=', '<=']
          : isDate
            ? ['between', '>=', '<=']
            : ['=', ':'],
        valueType: isNumeric
          ? ('numeric' as const)
          : isDate
            ? ('date' as const)
            : ('string' as const),
        displayName: c.title,
        description: c.title,
        descriptionKey: '',
        example: '',
        supportsPresence: true,
        docTypes: c.doc_types,
      };
    });
}

