.backend-banner {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 9999;
  background: var(--warning, #f59e0b);
  color: white;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}
