export default {
  methods: {
    removeSpaces(str: string) {
      return str.replace(/\s+/g, '');
    },

    getStringLastPart(fieldName: string, delimiter: string) {
      const parts = fieldName.split(delimiter);
      return parts.length > 1 ? +parts[1] : 0;
    },

    formatText(input: string, split = '_') {
      return input
        .split(split)
        .map(
          (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
        )
        .join(' ');
    },
    stringReplaceWithString(
      target: string,
      search: string,
      replacement: string,
    ): string {
      const finalString: string = target.split(search).join(replacement);
      return finalString;
    },
    normalizeString(value: string) {
      return value.toLowerCase().replace(/\s+/g, ' ').trim();
    },
  },
};
