<template>
  <BootErrorBanner />

  <router-view />

  <TolgeeProvider>
    <template v-if="false">
      <!-- VuePreloader temporarily disabled to fix console errors -->
      <!-- TODO: Re-enable after fixing component registration -->
    </template>
  </TolgeeProvider>
  <AppToaster />
  <OfflineOverlay />
  <CacheRefreshOverlay />
