// Need to either:
// 1. Register it globally in main boot file, or
// 2. Use a proper Quasar Loading component instead
// import { VuePreloader } from 'vue-preloader';
import { TolgeeProvider } from '@tolgee/vue';
import OfflineOverlay from 'src/components/OfflineOverlay.vue';
import { CacheRefreshOverlay } from 'src/components/UpdateNotification';
import BootErrorBanner from 'src/components/BootErrorBanner.vue';
import BackendUnavailableBanner from 'src/components/BackendUnavailableBanner.vue';
export default defineComponent({
  components: {
