    TolgeeProvider,
    OfflineOverlay,
    CacheRefreshOverlay,
    BootErrorBanner,
    BackendUnavailableBanner,
  },
  name: 'App',
  mounted() {
    const loader = document.getElementById('app-loading');
    if (loader) {
      loader.remove();
    }
    // Signal to the preboot error-capture script that the app successfully mounted.
    // This stops it from reporting us as "stuck" and lets it flush any buffered errors.
    if (typeof window !== 'undefined') {
      window.__appInitialized = true;
    }
  },
});
