import AbstractApiService from '../abstractApiService';
import { api } from 'pages/APIs';
import type {
  IdeasListResponse,
  IdeaSingleResponse,
  CreateIdeaPayload,
  UpdateIdeaPayload,
  VoteResponse,
  MyVotesResponse,
  CommentsListResponse,
  CreateCommentPayload,
} from 'src/types/api/ideas';

export default class IdeasApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getIdeas(params: {
    page?: number;
    page_size?: number;
    category?: string;
    status?: string;
    search?: string;
    sort?: string;
  }): Promise<IdeasListResponse> {
    const query = new URLSearchParams();
    if (params.page) query.append('page', params.page.toString());
    if (params.page_size) query.append('page_size', params.page_size.toString());
    if (params.category) query.append('category', params.category);
    if (params.status) query.append('status', params.status);
    if (params.search) query.append('search', params.search);
    if (params.sort) query.append('sort', params.sort);

    return super.get(`${api.ideas_list}?${query.toString()}`);
  }

  public async getIdea(id: string): Promise<IdeaSingleResponse> {
    return super.get(`${api.ideas_list}/${id}`);
  }

  public async createIdea(payload: CreateIdeaPayload): Promise<IdeaSingleResponse> {
    return super.post(api.ideas_list, payload);
  }

  public async toggleVote(ideaId: string): Promise<VoteResponse> {
    return super.post(`${api.ideas_list}/${ideaId}/vote`, {});
  }

  public async updateStatus(ideaId: string, status: string): Promise<IdeaSingleResponse> {
    return super.patch(`${api.ideas_list}/${ideaId}/status`, { status });
  }

  public async deleteIdea(ideaId: string): Promise<{ success: boolean }> {
    return super.delete(`${api.ideas_list}/${ideaId}`, {});
  }

  public async getMyVotes(): Promise<MyVotesResponse> {
    return super.get(api.ideas_my_votes);
  }

  public async updateIdea(ideaId: string, payload: UpdateIdeaPayload): Promise<IdeaSingleResponse> {
    return super.put(`${api.ideas_list}/${ideaId}`, payload);
  }

  public async getComments(ideaId: string): Promise<CommentsListResponse> {
    return super.get(`${api.ideas_list}/${ideaId}/comments`);
  }

  public async createComment(ideaId: string, payload: CreateCommentPayload): Promise<CommentsListResponse> {
    return super.post(`${api.ideas_list}/${ideaId}/comments`, payload);
  }

  public async deleteComment(ideaId: string, commentId: string): Promise<{ success: boolean }> {
    return super.delete(`${api.ideas_list}/${ideaId}/comments/${commentId}`, {});
  }

  public async uploadImage(file: File): Promise<{
    success: boolean;
    asset: { id: string; url: string; filename: string; mime_type: string };
  }> {
    const formData = new FormData();
    formData.append('file', file);
    return super.post(api.ideas_upload, formData);
  }
}
