/**
 * Auth SDK Service - Type-safe OAuth2 authentication using generated SDK
 *
 * This service wraps the generated TypeScript SDK (from openapi-typescript-codegen)
 * and integrates it with the existing doc2app authentication flow.
 *
 * Key features:
 * - Type-safe OAuth2 operations with compile-time checking
 * - Automatic token management via OpenAPI.TOKEN configuration
 * - Integration with Pinia stores (useAuthTokenStore, useUserStore)
 * - RFC 6749 compliant OAuth2 implementation
 *
 * @see /src/generated-auth-sdk - Generated from auth service OpenAPI spec
 */

import {
  OpenAPI,
  Oauth2V2Service,
  AuthService,
  OAuth2TokenRequest,
} from 'src/generated-auth-sdk';
import type {
  OAuth2TokenResponse,
  OAuth2ProfileResponse,
  SetSessionUserRequest,
  SetSessionUserResponse,
} from 'src/generated-auth-sdk';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { useUserStore } from 'src/store/User/user_details.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { LocalStorage, SessionStorage } from 'quasar';
import { AUTH_URL } from 'src/pages/APIs';

/**
 * Configure SDK with auth service URL and token management
 */
const initializeSdk = () => {
  // ✅ CRITICAL FIX: Use AUTH_URL from APIs.ts which respects APP_VUE_STAGE=local
  // This ensures the SDK uses localhost:5001 when testing locally
  const authUrl = AUTH_URL;

  OpenAPI.BASE = authUrl;

  // Configure credentials for cross-origin requests
  OpenAPI.WITH_CREDENTIALS = true;
  OpenAPI.CREDENTIALS = 'include';

  // Dynamic token resolver - fetches token from store when needed
  // IMPORTANT: Strip "Bearer " prefix if present because the SDK's request.ts
  // always adds "Bearer " in getHeaders(). The store's token field can contain
  // either a raw token or "Bearer <token>" depending on whether setAuthToken()
  // or setTokenInLocalStorage() was called last.
  OpenAPI.TOKEN = async () => {
    const authStore = useAuthTokenStore();
    const token = authStore.token || '';
    return token.startsWith('Bearer ') ? token.slice(7) : token;
  };
};

// Initialize on module load
initializeSdk();

/**
 * SDK-based Auth Service
 *
 * Provides type-safe OAuth2 authentication methods using the generated SDK.
 * Maintains compatibility with existing authApiService.ts interface.
 */
export class AuthSdkService {
  /**
   * Refresh OAuth2 access token using refresh token
   *
   * @param refreshToken - The refresh token from previous authentication
   * @returns OAuth2 token response with new access_token and refresh_token
   *
   * @example
   * ```typescript
   * const response = await authSdkService.refreshToken('tFnANP87rRMSCCuSwTT0Y5M0LmpUmPMbBow2F8zKCM');
   * // response.access_token, response.refresh_token, response.user_id
   * ```
   */
  public async refreshToken(
    refreshToken: string,
  ): Promise<OAuth2TokenResponse> {
    // ✅ RFC 6749 Compliance: Use public client with client_id parameter
    // This fixes the "invalid_client" error: "Could not extract client_id from Authorization header or form data"
    const request: OAuth2TokenRequest = {
      grant_type: 'refresh_token' as OAuth2TokenRequest.grant_type,
      refresh_token: refreshToken,
      client_id: 'frontend',
    };

    try {
      const response = await Oauth2V2Service.postV2Oauth2Token({
        formData: request,
      });

      // Type guard: ensure we got a successful response, not an error
      if ('access_token' in response) {
        const tokenResponse = response as OAuth2TokenResponse;

        // If user_id not in response, try to extract from JWT access_token
        if (!tokenResponse.user_id && tokenResponse.access_token) {
          try {
            const tokenParts = tokenResponse.access_token.split('.');
            if (tokenParts.length === 3) {
              const decoded = JSON.parse(atob(tokenParts[1]));
              tokenResponse.user_id =
                decoded.user_id || decoded.sub || decoded.id;
            }
          } catch {
            // Failed to decode JWT, that's okay - user_id might be null
          }
        }

        return tokenResponse;
      }

      throw new Error('Token refresh failed');
    } catch (error: any) {
      // Enhanced error logging for debugging intermittent refresh failures
      console.error('[AUTH_SDK] ❌ refreshToken error details:', {
        errorType: error?.constructor?.name || typeof error,
        body: error.body,
        message: error.message,
        status: error.status,
        statusCode: error.statusCode,
        response: error.response,
        // OAuth2 specific error fields
        error_code: error.body?.error || error.error,
        error_description: error.body?.error_description || error.error_description,
      });

      // Check for specific OAuth2 errors that indicate token reuse/replay
      const errorCode = error.body?.error || error.error;
      if (errorCode === 'invalid_grant' || errorCode === 'refresh_token_replay') {
        console.error('[AUTH_SDK] ⚠️ RACE CONDITION DETECTED: refresh_token was likely already used');
        console.error('[AUTH_SDK] This happens when multiple concurrent requests trigger refresh simultaneously');
      }

      throw error.body || error.message || error;
    }
  }

  /**
   * Authenticate user with username/password (OAuth2 password grant)
   *
   * @param username - User email
   * @param password - User password
   * @param scope - OAuth2 scope (default: 'profile')
   * @returns OAuth2 token response with access_token, refresh_token, and user_id
   *
   * @example
   * ```typescript
   * const response = await authSdkService.login('user@example.com', 'secret', 'profile');
   * // Store tokens and user_id for session establishment
   * ```
   */
  public async login(
    username: string,
    password: string,
    scope = 'profile offline_access', // Include offline_access to get refresh_token (DOCB-9171)
  ): Promise<OAuth2TokenResponse> {
    // ✅ FIX: RFC 6749 compliance - Use public client with client_id parameter
    // This fixes the "invalid_client" error: "Could not extract client_id from Authorization header or form data"
    // OAuth2 password grant requires client identification - using public client 'frontend' (no secret)
    const request: OAuth2TokenRequest = {
      grant_type: OAuth2TokenRequest.grant_type.PASSWORD,
      username,
      password,
      scope,
      client_id: 'frontend',
    };

    try {
      const response = await Oauth2V2Service.postV2Oauth2Token({
        formData: request,
      });

      if ('access_token' in response) {
        const tokenResponse = response as OAuth2TokenResponse;

        // If user_id not in response, try to extract from JWT access_token
        if (!tokenResponse.user_id && tokenResponse.access_token) {
          try {
            const tokenParts = tokenResponse.access_token.split('.');
            if (tokenParts.length === 3) {
              const decoded = JSON.parse(atob(tokenParts[1]));
              tokenResponse.user_id =
                decoded.user_id || decoded.sub || decoded.id;
            }
          } catch {
            // Failed to decode JWT, that's okay - user_id might be null
          }
        }

        return tokenResponse;
      }

      throw new Error('Login failed');
    } catch (error: any) {
      throw error.body || error.message || error;
    }
  }

  /**
   * Establish user session after OAuth2 authentication
   *
   * This is critical for the web app authentication flow:
   * 1. User authenticates via login() or refreshToken()
   * 2. Web app receives access_token
   * 3. Web app calls setUserSession() with {user_id, org_id}
   * 4. Session is established and user can access protected resources
   *
   * User ID is obtained from multiple sources in priority order:
   * 1. Directly passed as parameter
   * 2. From user store (if already loaded)
   * 3. From profile endpoint (getUserProfile())
   *
   * @param userId - User ID (optional, will fetch from profile if not provided)
   * @param orgId - Organization ID (optional, defaults to current org from store)
   * @returns Session confirmation with user_id and org_id
   *
   * @example
   * ```typescript
   * // Auto-fetch user_id from profile
   * const sessionResponse = await authSdkService.setUserSession(undefined, selectedOrgId);
   *
   * // Or provide user_id explicitly
   * const sessionResponse = await authSdkService.setUserSession('123', selectedOrgId);
   * ```
   */
  public async setUserSession(
    userId?: string,
    orgId?: string,
  ): Promise<SetSessionUserResponse> {
    const userStore = useUserStore();
    const authStore = useAuthTokenStore();

    // ✅ FIX: Hydrate Pinia state from LocalStorage before any token operations
    // This fixes race conditions where token exists in LocalStorage but Pinia state is empty
    // (e.g., after Login.vue sets token but before PrepareDashboard accesses it)
    authStore.hydrateFromLocalStorage();

    // Layer 3: Enhanced token validation with 2-minute expiry buffer
    // Prevents token from expiring DURING the API call due to network latency
    // This is the FIRST API call in PrepareDashboard setup - critical safety net
    // NOTE: Skip refresh for external tokens (TokenLogin.vue sets ignore_token_validation=true)
    // External tokens have no refresh_token and don't use OAuth refresh flow
    if (!authStore.ignore_token_validation) {
      const tokenInfo = authStore.getTokenDetails();

      if (tokenInfo && tokenInfo.expire_time) {
        const minutesRemaining = Math.floor(
          (new Date(tokenInfo.expire_time).getTime() - Date.now()) / 60000
        );

        // Refresh if token expires in less than 2 minutes (safety buffer for network delays)
        if (minutesRemaining < 2) {
          console.log(
            `[AUTH_SDK] setUserSession: Token expires in ${minutesRemaining} minutes (<2min buffer), refreshing proactively`,
          );
          const refreshSucceeded = await authStore.refreshToken();
          if (!refreshSucceeded) {
            console.error(
              '[AUTH_SDK] setUserSession: Token refresh failed - cannot establish session',
            );
            throw new Error('Token refresh failed. Please log in again to continue.');
          }
          console.log(
            '[AUTH_SDK] setUserSession: Token refreshed successfully, proceeding with session establishment',
          );
        } else {
          console.log(
            `[AUTH_SDK] setUserSession: Token valid for ${minutesRemaining} more minutes, proceeding without refresh`,
          );
        }
      }
    } else {
      console.log(
        '[AUTH_SDK] setUserSession: Skipping token refresh for external token (ignore_token_validation=true)',
      );
    }

    // Step 1: Get user_id from parameter
    let effectiveUserId = userId;
    console.log(
      '[AUTH_SDK] setUserSession() called with userId:',
      userId,
      'orgId:',
      orgId,
    );

    // Step 2: If not provided, check userStore
    if (!effectiveUserId) {
      effectiveUserId = userStore.getUserDetailByKey('id');
      console.log(
        '[AUTH_SDK] Checking userStore for user_id:',
        effectiveUserId,
      );
    }

    // Step 3: If still not found, try to decode from JWT access_token (opaque tokens won't work but try anyway)
    if (!effectiveUserId && authStore.token) {
      try {
        const tokenParts = authStore.token.split('.');
        if (tokenParts.length === 3) {
          const decoded = JSON.parse(atob(tokenParts[1]));
          effectiveUserId = decoded.user_id || decoded.sub || decoded.id;
          console.log(
            '[AUTH_SDK] Extracted user_id from JWT token:',
            effectiveUserId,
          );
        }
      } catch (e) {
        console.log(
          '[AUTH_SDK] Token decode failed (likely opaque token, which is expected)',
        );
      }
    }

    // Step 4: If still not found, fetch from profile endpoint (as last resort)
    if (!effectiveUserId && authStore.token) {
      try {
        console.log(
          '[AUTH_SDK] Attempting to fetch user_id from profile endpoint...',
        );
        const profile = await this.getUserProfile();
        if (profile.user && profile.user.id) {
          effectiveUserId = String(profile.user.id);
          console.log(
            '[AUTH_SDK] Successfully fetched user_id from profile:',
            effectiveUserId,
          );
        }
      } catch (profileError: any) {
        console.error(
          '[AUTH_SDK] CRITICAL: Profile fetch failed with error:',
          profileError?.message || profileError,
        );
        console.error(
          '[AUTH_SDK] This may be a CORS issue or auth service configuration problem',
        );

        // As last-ditch effort, try to extract user_id from stored login response
        // CRITICAL FIX: Use 'token_details' (with typo) to match what auth_token.store.ts actually saves
        // CRITICAL FIX: Use Quasar's LocalStorage.getItem() which handles "__q_objt|" prefix and auto-parses
        const tokenDetails = LocalStorage.getItem('token_details') as any;
        if (tokenDetails && tokenDetails.user_id) {
          effectiveUserId = String(tokenDetails.user_id);
          console.log(
            '[AUTH_SDK] Fallback: Retrieved user_id from stored token_details:',
            effectiveUserId,
          );
        }
      }
    }

    if (!effectiveUserId) {
      const errorMsg =
        'user_id is required for session establishment. All extraction methods failed.';
      console.error('[AUTH_SDK] CRITICAL:', errorMsg);
      console.error(
        '[AUTH_SDK] Debug info - authStore.token exists:',
        !!authStore.token,
      );
      console.error(
        '[AUTH_SDK] Debug info - userStore id:',
        userStore.getUserDetailByKey('id'),
      );
      throw new Error(errorMsg);
    }

    // Fetch profile data for org_id resolution when org_id is not already available.
    // This is needed because user_id may be resolved from JWT (Step 3) without ever
    // hitting the profile endpoint, leaving profileData null and org_id unresolvable.
    let profileData = null;
    const needsOrgId = !orgId && !getOrgId();
    if (needsOrgId && authStore.token) {
      try {
        const profile = await this.getUserProfile();
        profileData = profile?.user || null;
      } catch (e) {
        console.warn('[AUTH_SDK] Profile fetch for org_id resolution failed:', (e as Error)?.message);
      }
    }

    // Get org_id from parameter, helper, or profile
    let effectiveOrgId = orgId || getOrgId();
    console.log(
      '[AUTH_SDK] Effective org_id after initial check:',
      effectiveOrgId,
    );

    // If org_id not available from parameter/helper, try to get from profile data
    if (
      !effectiveOrgId &&
      profileData?.organisations &&
      Array.isArray(profileData.organisations) &&
      profileData.organisations.length > 0
    ) {
      effectiveOrgId = String(profileData.organisations[0].id);
      console.log(
        '[AUTH_SDK] Retrieved org_id from profile data:',
        effectiveOrgId,
      );
    }

    // If still not available, try stored token data
    // Declare tokenDetails outside try block so it's accessible later for logging
    let tokenDetails: any = null;
    if (!effectiveOrgId) {
      try {
        // CRITICAL FIX: Use 'token_details' (with typo) to match what auth_token.store.ts actually saves
        // CRITICAL FIX: Use Quasar's LocalStorage.getItem() which handles "__q_objt|" prefix and auto-parses
        tokenDetails = LocalStorage.getItem('token_details') as any;
        if (tokenDetails) {
          // Try direct org_id field
          if (tokenDetails.org_id) {
            effectiveOrgId = String(tokenDetails.org_id);
            console.log(
              '[AUTH_SDK] Fallback: Retrieved org_id from stored token_details.org_id:',
              effectiveOrgId,
            );
          }
          // Try organisations array
          else if (
            tokenDetails.organisations &&
            Array.isArray(tokenDetails.organisations) &&
            tokenDetails.organisations.length > 0
          ) {
            effectiveOrgId = String(tokenDetails.organisations[0].id);
            console.log(
              '[AUTH_SDK] Fallback: Retrieved org_id from stored token_details.organisations[0]:',
              effectiveOrgId,
            );
          }
        }
      } catch (e) {
        console.error('[AUTH_SDK] Error reading stored token data:', e);
      }
    }
    if (!effectiveOrgId) {
      console.warn('[AUTH_SDK] ⚠️ No org_id found for session establishment');
      console.warn(
        '[AUTH_SDK] Profile organisations:',
        profileData?.organisations?.length || 0,
      );
      console.warn(
        '[AUTH_SDK] Token organisations:',
        tokenDetails?.organisations?.length || 0,
      );
      console.warn('[AUTH_SDK] User ID:', effectiveUserId);
      console.warn(
        '[AUTH_SDK] Proceeding with session establishment - backend will assign default org or handle gracefully',
      );
      // Don't throw - allow session establishment to proceed
      // Backend can assign default org or return error if org is truly required
    }

    // Build request payload - only include org_id if available
    const request: SetSessionUserRequest = {
      user_id: Number(effectiveUserId),
    };

    // Only add org_id to payload if we have one
    if (effectiveOrgId) {
      request.org_id = effectiveOrgId;
      console.log(
        '[AUTH_SDK] Including org_id in session request:',
        effectiveOrgId,
      );
    } else {
      console.warn(
        '[AUTH_SDK] Session request WITHOUT org_id - relying on backend to assign',
      );
    }

    try {
      console.log(
        '[AUTH_SDK] setUserSession: Setting session (credentials mode)...',
      );
      const rawResponse = await Oauth2V2Service.postV2Oauth2SetSessionUser({
        requestBody: request,
      });

      // Type guard: Check if response is Error before accessing properties
      if (rawResponse instanceof Error) {
        console.error(
          '[AUTH_SDK] Session establishment returned error:',
          rawResponse,
        );
        throw rawResponse;
      }

      // Type assertion: Tell TypeScript this is SetSessionUserResponse, not Error
      const response = rawResponse as SetSessionUserResponse;
      console.log('[AUTH_SDK] ✓ Session request successful');

      // Extract org_id from response (SetSessionUserResponse only has org_id property)
      const sessionOrgId = response.org_id || effectiveOrgId; // Fallback to what we passed in

      if ('user_id' in response && sessionOrgId) {
        // Store the org_id in LocalStorage so it's accessible throughout the app via getUserDetailByKey
        // This is critical for ACL system and other components that call getOrgId()
        // ✅ FIX: Use Quasar's LocalStorage wrapper to properly retrieve and decode stored objects
        // CRITICAL FIX: Defensive handling in case LocalStorage returns a string instead of object
        let userDetails = LocalStorage.getItem('user_details') as any;
        if (typeof userDetails === 'string') {
          try {
            userDetails = JSON.parse(userDetails);
          } catch {
            userDetails = {};
          }
        }
        userDetails = userDetails || {};
        userDetails.org_id = String(sessionOrgId);
        LocalStorage.set('user_details', userDetails);
        console.log(
          `[AUTH_SDK] ✓ Stored org_id in LocalStorage: ${sessionOrgId}`,
        );
        console.log(
          '[AUTH_SDK] user_details after setSessionUser:',
          JSON.stringify(userDetails),
        );

        // CRITICAL FIX: Store org_id in SessionStorage (survives clearAllStorage)
        // SessionStorage is checked first by getOrgId() and is protected from clearAllStorage
        // BUGFIX: Use native sessionStorage instead of Quasar wrapper (Quasar may have serialization issues)
        const orgIdString = String(sessionOrgId);
        try {
          // Try Quasar's wrapper first
          SessionStorage.set('active_org_id', orgIdString);
          // Fallback to native sessionStorage to ensure it's set
          if (typeof window !== 'undefined' && window.sessionStorage) {
            window.sessionStorage.setItem('active_org_id', orgIdString);
          }
          console.log(
            `[AUTH_SDK] ✓ Stored org_id in SessionStorage (protected from clearAllStorage): ${sessionOrgId}`,
          );
        } catch (storageError) {
          console.error(
            '[AUTH_SDK] CRITICAL ERROR: Failed to store org_id in SessionStorage:',
            storageError,
          );
        }
      } else if ('user_id' in response && !sessionOrgId) {
        // Session established but no org_id returned
        console.warn(
          '[AUTH_SDK] ⚠️ Session established but no org_id in response',
        );
        console.warn(
          '[AUTH_SDK] User may have limited access without organization',
        );
        console.warn('[AUTH_SDK] Response:', JSON.stringify(response, null, 2));
        // Don't fail - some users might not need org_id
        // Application will need to handle this case gracefully
      } else {
        console.error(
          '[AUTH_SDK] ❌ Invalid session response - missing user_id',
        );
        console.error(
          '[AUTH_SDK] Response:',
          JSON.stringify(response, null, 2),
        );
      }

      // CRITICAL: Add a tiny delay (microtask) to ensure localStorage is flushed before returning
      // This prevents race conditions in components that immediately read org_id after setUserSession() completes
      if (sessionOrgId) {
        await new Promise((resolve) => {
          // Use microtask (Promise) instead of setTimeout to be faster, but ensure localStorage flush
          // CRITICAL FIX: Use Quasar's LocalStorage.getItem() which handles "__q_objt|" prefix and auto-parses
          const verify = LocalStorage.getItem('user_details') as any;
          const verifySession = SessionStorage.getItem('active_org_id');
          if (
            verify &&
            verify.org_id === String(sessionOrgId) &&
            verifySession === String(sessionOrgId)
          ) {
            console.log(
              '[AUTH_SDK] ✓ Verified org_id in both LocalStorage and SessionStorage after set',
            );
            resolve(true);
          } else {
            console.log(
              '[AUTH_SDK] ⚠️ WARNING: org_id verification failed, localStorage value:',
              JSON.stringify(verify),
              'SessionStorage value:',
              verifySession,
            );
            resolve(false);
          }
        });
      }

      return response as SetSessionUserResponse;

      throw new Error('Session establishment failed');
    } catch (error: any) {
      const errorMessage =
        error.body?.message || error.message || String(error);
      const isCorsError =
        errorMessage.includes('CORS') ||
        errorMessage.includes('Access-Control') ||
        errorMessage.includes('Failed to fetch') ||
        error.status === 0;

      if (isCorsError) {
        console.error('[AUTH_SDK] ❌ Session endpoint CORS error:', {
          isCorsError,
          message: errorMessage,
          status: error.status,
        });
        const corsHint =
          '\n⚠️  CORS Configuration Issue:\n' +
          '  - Backend is missing: Access-Control-Allow-Credentials: true\n' +
          '  - Backend should use specific origins, not wildcard (*)\n' +
          '  - Issue is in cloudintegration_subscription/config.py CORS settings';
        console.error('[AUTH_SDK] CORS Error Details:', corsHint);
        throw new Error(
          `Session establishment failed due to CORS error. ${corsHint}`,
        );
      }

      throw error.body || error.message || error;
    }
  }

  /**
   * Get complete user profile with organizations and subscription details
   *
   * Returns comprehensive user information including:
   * - User basic information (id, email, name, etc.)
   * - All organizations the user belongs to
   * - Sub-organizations within those organizations
   * - Active subscription details
   * - Total sub-organization count
   *
   * ⚠️ CORS Note: This endpoint requires credentials mode and proper CORS configuration
   * on the auth service backend. If CORS errors occur, check that the backend has:
   * - Access-Control-Allow-Credentials: true
   * - Specific origins (not wildcard *) in Access-Control-Allow-Origin
   *
   * @returns Complete user profile
   * @throws Error if profile retrieval fails after retries
   *
   * @example
   * ```typescript
   * const profile = await authSdkService.getUserProfile();
   * // profile.user, profile.organisations, profile.subscription
   * ```
   */
  public async getUserProfile(
    retryCount = 0,
    maxRetries = 2,
  ): Promise<OAuth2ProfileResponse> {
    try {
      console.log(
        '[AUTH_SDK] getUserProfile: Fetching profile endpoint (credentials mode)...',
      );
      const response = await Oauth2V2Service.getV2Oauth2Profile();

      // DEBUG: Log the actual response structure to diagnose format mismatch
      console.log('[AUTH_SDK] Raw profile response:', JSON.stringify(response, null, 2));
      console.log('[AUTH_SDK] Response keys:', Object.keys(response));

      if ('user' in response) {
        console.log('[AUTH_SDK] ✓ Profile fetch successful');
        return response as OAuth2ProfileResponse;
      }

      // If no 'user' field, log the actual structure for debugging
      console.error('[AUTH_SDK] Profile response missing "user" field');
      console.error('[AUTH_SDK] Response structure:', response);

      throw new Error('Profile retrieval failed - invalid response format');
    } catch (error: any) {
      const errorMessage =
        error.body?.message || error.message || String(error);
      const isCorsError =
        errorMessage.includes('CORS') ||
        errorMessage.includes('Access-Control') ||
        errorMessage.includes('Failed to fetch') ||
        error.status === 0; // Network error often indicates CORS

      console.log(
        `[AUTH_SDK] ❌ Profile fetch error (attempt ${retryCount + 1}/${maxRetries + 1}):`,
        {
          isCorsError,
          message: errorMessage,
          status: error.status,
        },
      );

      // Retry on transient errors (CORS, network) but not on auth errors (401, 403)
      if (isCorsError && retryCount < maxRetries) {
        console.log(
          `[AUTH_SDK] Retrying profile fetch in 1 second... (${retryCount + 1}/${maxRetries})`,
        );
        await new Promise((resolve) => setTimeout(resolve, 1000));
        return this.getUserProfile(retryCount + 1, maxRetries);
      }

      // If CORS error after retries, provide helpful guidance
      if (isCorsError) {
        const corsHint =
          '\n⚠️  CORS Configuration Issue:\n' +
          '  - Backend is missing: Access-Control-Allow-Credentials: true\n' +
          '  - Backend should use specific origins, not wildcard (*)\n' +
          '  - Issue is in cloudintegration_subscription/config.py CORS settings';
        console.error('[AUTH_SDK] CORS Error Details:', corsHint);
        throw new Error(
          `Profile retrieval failed due to CORS error. ${corsHint}`,
        );
      }

      // For other errors, re-throw with more context
      throw error.body || error.message || error;
    }
  }

  /**
   * Update SDK configuration (base URL, credentials, token resolver)
   *
   * @param config - Partial OpenAPI configuration to update
   *
   * @example
   * ```typescript
   * authSdkService.configure({
   *   BASE: 'https://stage.auth.docbits.com',
   *   TOKEN: async () => customTokenGetter()
   * });
   * ```
   */
  public configure(config: Partial<typeof OpenAPI>): void {
    Object.assign(OpenAPI, config);
  }

  /**
   * Get current SDK configuration
   *
   * @returns Current OpenAPI configuration
   */
  public getConfig(): typeof OpenAPI {
    return OpenAPI;
  }
}

// Export singleton instance
export const authSdkService = new AuthSdkService();

// Export for default import compatibility
export default authSdkService;
